action.mutation:
mutation CreateLoad($payload: [LoadCreatePayloadInput!]!) {
        mutation: createLoad(payload: $payload) { 
          id
          number
      }
    }

mutation UpdateLoad($payload: [LoadUpdatePayloadInput!]!) {
        mutation: updateLoad(payload: $payload) { 
          id
          number
      }
    }

mutation DeleteLoad($payload: [LoadDeletePayloadInput!]!) {
        mutation: deleteLoad(payload: $payload) { 
          id
          number
      }
    }
